package techguns.gametest;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.*;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.gametest.*;
import techguns.*;
import techguns.machines.*;
import techguns.capabilities.TGExtendedPlayer;
@GameTestHolder(Techguns.MODID) @PrefixGameTestTemplate(false)
public final class BenchGameTests {
    private static BenchEntity bench(GameTestHelper h,BenchKind kind){h.setBlock(1,1,1,TGBenches.BLOCKS.get(kind).get());return (BenchEntity)h.getBlockEntity(new BlockPos(1,1,1));}
    private static net.minecraft.world.entity.player.Player player(GameTestHelper h){var p=h.makeMockSurvivalPlayer();p.setPos(h.absoluteVec(new Vec3(1.5,1,1.5)));return p;}
    @GameTest(template="empty") public static void repairRequiresAllMaterialsAndKeepsItemNBT(GameTestHelper h){var b=bench(h,BenchKind.REPAIR);var armor=TGEquipment.ARMOR.get("steam_chestplate").get();var target=armor.getDefaultInstance();target.setDamageValue(target.getMaxDamage()-1);target.getOrCreateTag().putByte("camo",(byte)2);armor.charge(target,1234);b.inventory.setStackInSlot(0,new ItemStack(TGItems.STEAMARMOR_PLATE.get(),3));h.assertFalse(b.repair(target),"Three plates cannot pay for a four-plate repair");h.assertTrue(b.inventory.getStackInSlot(0).getCount()==3&&target.getDamageValue()>0,"Failed repair is atomic and spends nothing");b.inventory.setStackInSlot(0,new ItemStack(TGItems.STEAMARMOR_PLATE.get(),4));h.assertTrue(b.repair(target)&&target.getDamageValue()==0&&b.inventory.getStackInSlot(0).isEmpty(),"Full repair spends exactly the required plates");h.assertTrue(armor.power(target)==1234&&target.getTag().getByte("camo")==2,"Repair preserves power and camouflage");h.succeed();}
    @GameTest(template="empty") public static void camoButtonsUpdateHeldWornAndExtraSlotItemsWithoutResettingAmmo(GameTestHelper h){var b=bench(h,BenchKind.CAMO);var p=player(h);var menu=new BenchMenu(1,p.getInventory(),b);var gun=TGuns.m4.get();var stack=gun.getDefaultInstance();gun.setAmmo(stack,3);b.inventory.setStackInSlot(0,stack);menu.clickMenuButton(p,2);h.assertTrue(stack.getTag().getByte("camo")==1&&gun.getCurrentAmmo(stack)==3,"Camouflage changes retain the exact remaining gun ammunition");menu.clickMenuButton(p,3);h.assertTrue(stack.getTag().getByte("camo")==0,"Reverse button cycles backwards");var helmet=TGEquipment.ARMOR.get("t1_scout_helmet").get().getDefaultInstance();p.setItemSlot(EquipmentSlot.HEAD,helmet);menu.clickMenuButton(p,4);h.assertTrue(helmet.getTag().getByte("camo")==1,"Worn armor can be recolored directly");var pack=TGAccessories.JETPACK.get().getDefaultInstance();pack.setDamageValue(75);TGExtendedPlayer.get(p).tg_inventory.setItem(1,pack);menu.clickMenuButton(p,12);h.assertTrue(pack.getTag().getByte("camo")==1&&pack.getDamageValue()==75,"Additional-slot camouflage must retain device fuel");h.succeed();}
    @GameTest(template="empty") public static void vanillaCamoCyclesFlattenedBlocksAndPreservesStackCount(GameTestHelper h){var b=bench(h,BenchKind.CAMO);var p=player(h);var menu=new BenchMenu(1,p.getInventory(),b);b.inventory.setStackInSlot(0,new ItemStack(Items.WHITE_WOOL,17));menu.clickMenuButton(p,3);h.assertTrue(b.inventory.getStackInSlot(0).is(Items.BLACK_WOOL)&&b.inventory.getStackInSlot(0).getCount()==17,"Reverse cycling wraps white to black after Minecraft metadata flattening");menu.clickMenuButton(p,2);h.assertTrue(b.inventory.getStackInSlot(0).is(Items.WHITE_WOOL),"Forward cycle wraps back to white");h.succeed();}
    @GameTest(template="empty") public static void armorUpgradeSpendsExperienceAndOneModuleOnTake(GameTestHelper h){var b=bench(h,BenchKind.UPGRADE);var p=player(h);var menu=new BenchMenu(1,p.getInventory(),b);var armor=TGEquipment.ARMOR.get("t1_combat_chestplate").get().getDefaultInstance();armor.getOrCreateTag().putByte("camo",(byte)2);armor.setDamageValue(30);b.inventory.setStackInSlot(0,armor);b.inventory.setStackInSlot(1,new ItemStack(TGItems.UPGRADE_PROTECTION_1.get(),2));menu.broadcastChanges();h.assertTrue(!menu.result.getItem(0).isEmpty()&&!menu.slots.get(2).mayPickup(p),"Upgrade preview exists but cannot be taken without experience");p.giveExperiencePoints(100);var result=menu.quickMoveStack(p,2);h.assertTrue(!result.isEmpty()&&EnchantmentHelper.getItemEnchantmentLevel(Enchantments.ALL_DAMAGE_PROTECTION,result)==1,"Taking output applies the source enchantment");h.assertTrue(p.totalExperience==80&&b.inventory.getStackInSlot(0).isEmpty()&&b.inventory.getStackInSlot(1).getCount()==1,"Taking an upgrade spends twenty XP and exactly one module");h.assertTrue(result.getDamageValue()==30&&result.getTag().getByte("camo")==2,"Upgrades preserve item damage and other NBT");h.succeed();}
    @GameTest(template="empty") public static void upgradesChargeOnlyLevelDifferenceAndRejectDowngrades(GameTestHelper h){var armor=TGEquipment.ARMOR.get("t1_combat_helmet").get().getDefaultInstance();armor.enchant(Enchantments.ALL_DAMAGE_PROTECTION,1);var upgraded=ArmorUpgrades.result(armor,TGItems.UPGRADE_PROTECTION_3.get().getDefaultInstance());h.assertTrue(upgraded.xp()==40&&EnchantmentHelper.getItemEnchantmentLevel(Enchantments.ALL_DAMAGE_PROTECTION,upgraded.stack())==3,"Upgrading from one to three charges only two levels of source XP cost");h.assertTrue(ArmorUpgrades.result(upgraded.stack(),TGItems.UPGRADE_PROTECTION_2.get().getDefaultInstance()).stack().isEmpty(),"A lower module never downgrades an existing enchantment");h.assertTrue(ArmorUpgrades.result(TGuns.pistol.get().getDefaultInstance(),TGItems.UPGRADE_PROTECTION_1.get().getDefaultInstance()).stack().isEmpty(),"Armor upgrade modules cannot enchant guns");h.succeed();}
    @GameTest(template="empty") public static void ownerOnlyModeRejectsOtherPlayersAndSurvivesSaving(GameTestHelper h){var b=bench(h,BenchKind.CAMO);var owner=player(h);var guest=player(h);b.access.place(owner);h.assertTrue(b.access.allows(guest)&&!b.access.toggle(guest),"Public bench remains usable but only its owner can change security");h.assertTrue(b.access.toggle(owner)&&!b.access.allows(guest),"Owner can enable restricted access");var menu=new BenchMenu(1,guest.getInventory(),b);h.assertTrue(!menu.stillValid(guest)&&!menu.clickMenuButton(guest,2),"Previously opened menus cannot bypass private access");var copy=new BenchEntity(b.getBlockPos(),b.getBlockState());copy.load(b.saveWithoutMetadata());h.assertTrue(copy.access.allows(owner)&&!copy.access.allows(guest),"Ownership and private mode survive block entity persistence");h.succeed();}
}
